];

function renderCourses(tab) {
  const grid = document.getElementById('courseGrid');
  const filtered = tab === 'featured'
    ? allCourses
    : allCourses.filter(c => c.categories.includes(tab));
  const courses = filtered.length > 0 ? filtered : allCourses.slice(0, 4);

  grid.innerHTML = courses.map((c, i) => `
    <div class="course-card" style="animation: fadeInUp 0.4s ease ${i * 0.06}s both">
      <div class="course-thumb ${c.thumb}">
        <span style="font-size:40px">${c.icon}</span>
        <div class="course-thumb-overlay">
          <div class="play-icon">&#9654;</div>
        </div>
      </div>
      <div class="course-info">
        <div class="course-title-text">${c.title}</div>
        <div class="course-instructor">${c.instructor}</div>
        <div class="course-meta">
          <span class="course-meta-item"><span class="course-meta-icon">&#128100;</span> ${c.students} students</span>
          <span class="course-meta-item"><span class="course-meta-icon">&#128337;</span> ${c.duration}</span>
        </div>
      </div>
    </div>
  `).join('');
}

// Tab switching
document.querySelectorAll('.course-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.course-tab').forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    renderCourses(tab.dataset.tab);
  });
});

renderCourses('featured');

// ========== FAQ ACCORDION ==========
document.querySelectorAll('.faq-trigger').forEach(trigger => {
  trigger.addEventListener('click', () => {
    const item = trigger.parentElement;
    const isActive = item.classList.contains('active');
    document.querySelectorAll('.faq-item').forEach(i => {
      i.classList.remove('active');
      i.querySelector('.faq-trigger').setAttribute('aria-expanded', 'false');
    });
    if (!isActive) {
      item.classList.add('active');
      trigger.setAttribute('aria-expanded', 'true');
    }
  });
});

// ========== TEACHER CAROUSEL ==========
function scrollTeachers(dir) {
  const el = document.getElementById('teacherScroll');
  el.scrollBy({ left: dir * 280, behavior: 'smooth' });
}

// ========== SCROLL REVEAL ==========
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    }
  });
}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
</script>

